 "content": "from collections import Counter


def _runs(line, bg):
    out = []
    i = 0
    while i < len(line):
        if line[i] == bg:
            i += 1
            continue
        color = line[i]
        j = i + 1
        while j < len(line) and line[j] == color:
            j += 1
        out.append((color, i, j))  # half-open interval
        i = j
    return out


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find equal-length, same-color runs on opposite borders.
    pairs = []
    for first, second, axis in (
        (_runs(grid[0], bg), _runs(grid[-1], bg), "h"),
        (_runs([grid[r][0] for r in range(h)], bg),
         _runs([grid[r][-1] for r in range(h)], bg), "v"),
    ):
        for a in first:
            for b in second:
                if a[0] == b[0] and a[2] - a[1] == b[2] - b[1]:
                    pairs.append((a, b, axis))
    if not pairs:
        return [row[:] for row in grid]

    # The task's edge bars form one paired launcher. Prefer the pair that
    # leaves the most non-background interior marks to select offsets.
    def pair_score(pair):
        a, b, axis = pair
        cells = set()
        if axis == "h":
            cells.update((0, c) for c in range(a[1], a[2]))
            cells.update((h - 1, c) for c in range(b[1], b[2]))
        else:
            cells.update((r, 0) for r in range(a[1], a[2]))
            cells.update((r, w - 1) for r in range(b[1], b[2]))
        marks = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] != bg and (r, c) not in cells]
        return (len(marks), -abs((a[2] - a[1]) - 1))

    a, b, axis = max(pairs, key=pair_score)
    bar_cells = set()
    if axis == "h":
        bar_cells.update((0, c) for c in range(a[1], a[2]))
        bar_cells.update((h - 1, c) for c in range(b[1], b[2]))
    else:
        bar_cells.update((r, 0) for r in range(a[1], a[2]))
        bar_cells.update((r, w - 1) for r in range(b[1], b[2]))

    marks = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != bg and (r, c) not in bar_cells]
    if not marks:
        return [row[:] for row in grid]
    paint = Counter(v for _, _, v in marks).most_common(1)[0][0]

    # A mark whose coordinate lies over a bar selects that offset in the
    # paired bar. Both corresponding border cells then cast inward rays.
    active = set()
    for r, c, _ in marks:
        pos = c if axis == "h" else r
        for run in (a, b):
            if run[1] <= pos < run[2]:
                active.add(pos - run[1])

    out = [row[:] for row in grid]

    def cast(r, c, dr, dc):
        while 0 <= r < h and 0 <= c < w:
            value = grid[r][c]
            if value == paint:
                out[r][c] = 4
                return
            if value != bg:
                return
            out[r][c] = paint
            r += dr
            c += dc

    for offset in sorted(active):
        if axis == "h":
            for run, edge in ((a, 0), (b, h - 1)):
                c = run[1] + offset
                dr = 1 if edge == 0 else -1
                cast(edge + dr, c, dr, 0)
        else:
            for run, edge in ((a, 0), (b, w - 1)):
                r = run[1] + offset
                dc = 1 if edge == 0 else -1
                cast(r, edge + dc, 0, dc)
    return out


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin)), separators=(",", ":")))

